/// The class of the characterinfo record named `name`, `None` when it is
/// neither a bag catch nor an `Animal_*` record.
pub fn species_class(name: &str) -> Option<SpeciesClass> {
    SPECIES
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .and_then(|i| SPECIES.get(i))
        .map(|&(_, c)| c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_unique() {
        assert!(SPECIES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    fn count(c: SpeciesClass) -> usize {
        SPECIES.iter().filter(|(_, x)| *x == c).count()
    }

    /// The counts on build 26361232.
    #[test]
    fn pinned_counts() {
        assert_eq!(count(SpeciesClass::Bug), 81);
        assert_eq!(count(SpeciesClass::Fish), 47);
        assert_eq!(count(SpeciesClass::Critter), 36);
        assert_eq!(count(SpeciesClass::NotHandCatchable), 843);
    }

    #[test]
    fn spot_checks() {
        assert_eq!(species_class("Animal_Raccoon_Wild_30042"), Some(SpeciesClass::NotHandCatchable));
        assert_eq!(species_class("Animal_Duck_Wild_30020"), Some(SpeciesClass::NotHandCatchable));
        assert_eq!(species_class("Riding_Iguana_1"), None);
        assert_eq!(species_class("Animal_Iguana_Wild_30069"), Some(SpeciesClass::Critter));
        assert_eq!(species_class("Animal_Insect_Lobster"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_Insect_Sea_Slater"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_RiceFish"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_Sparrow_Wild_30071"), Some(SpeciesClass::Critter));
        assert_eq!(species_class("Animal_Insect_GrassHopper"), Some(SpeciesClass::Bug));
    }
}
